/**
 * @method
 * @name bittrade#fetchTime
 * @description fetches the current integer timestamp in milliseconds from the exchange server
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int} the current integer timestamp in milliseconds from the exchange server
 */
func (this *Bittrade) FetchTimeAsync(optionalArgs ...any) <-chan AsyncResult[*int64] {
	ch := make(chan AsyncResult[*int64], 1)
	go this.fetchTimeBody(ch, optionalArgs...)
	return ch
}
func (this *Bittrade) fetchTimeBody(ch chan AsyncResult[*int64], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.PublicGetCommonTimestamp(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value

	ch <- AsyncResult[*int64]{Value: this.SafeInteger(response, "data")}
	return nil
}
func (this *Bittrade) FetchTradingLimitsAsync(optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.fetchTradingLimitsBody(ch, optionalArgs...)
	return ch
}
func (this *Bittrade) fetchTradingLimitsBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// this method should not be called directly, use loadTradingLimits () instead
	//  by default it will try load withdrawal fees of all currencies (with separate requests)
	//  however if you define symbols = [ 'ETH/BTC', 'LTC/BTC' ] in args it will only load those
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbolsResolved any = func() any {
		if symbols == nil {
			return this.Symbols
		}
		return symbols
	}()
	if IsEqual(symbolsResolved, nil) {
		panic(ExchangeError(this.Id + " markets not loaded"))
	}
	var result map[string]any = map[string]any{}
	for i := 0; i < GetArrayLength(symbolsResolved); i++ {
		var symbol *string = SafeStringPtr(GetValue(symbolsResolved, i))
		r1 := <-this.FetchTradingLimitsByIdAsync(this.MarketId(symbol), params)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var r1ValueBox any = nil
		if r1.Value != nil {
			r1ValueBox = r1.Value
		}
		AddElementToObject(result, symbol, r1ValueBox)
	}

	ch <- AsyncResult[map[string]any]{Value: result}
	return nil
}
func (this *Bittrade) FetchTradingLimitsByIdAsync(id any, optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.fetchTradingLimitsByIdBody(ch, id, optionalArgs...)
	return ch
}
