func (this *Bittrade) fetchTradesBody(ch chan AsyncResult[[]Trade], symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	limit := GetArg(optionalArgs, 1, 1000)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}
	if limit != nil {
		request["size"] = mathMin(limit, 2000)
	}

	r1 := <-this.MarketGetHistoryTrade(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "status": "ok",
	//         "ch": "market.btcusdt.trade.detail",
	//         "ts": 1583497692365,
	//         "data": [
	//             {
	//                 "id": 105005170342,
	//                 "ts": 1583497692182,
	//                 "data": [
	//                     {
	//                         "amount": 0.010411000000000000,
	//                         "trade-id": 102090736910,
	//                         "ts": 1583497692182,
	//                         "id": 10500517034273194594947,
	//                         "price": 9096.050000000000000000,
	//                         "direction": "sell"
	//                     }
	//                 ]
	//             },
	//             // ...
	//         ]
	//     }
	//
	var data []any = SafeListTyped(response, "data")
	var result []any = []any{}
	for i := 0; i < len(data); i++ {
		var trades []any = SafeListTyped(data[i], "data")
		for j := 0; j < len(trades); j++ {
			var trade map[string]any = TradeToMap(this.ParseTrade(trades[j], market))
			result = append(result, trade)
		}
	}
	result = this.SortBy(result, "timestamp")

	ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.FilterBySymbolSinceLimit(result, this.SafeString(market, "symbol"), since, limit))}
	return nil
}
