func (this *Bittrade) ParseOrder(order any, optionalArgs ...any) Order {
	//
	//     {                  id:  13997833014,
	//                    "symbol": "ethbtc",
	//              "account-id":  3398321,
	//                    "amount": "0.045000000000000000",
	//                     "price": "0.034014000000000000",
	//              "created-at":  1545836976871,
	//                      "type": "sell-limit",
	//            "field-amount": "0.045000000000000000", // they have fixed it for filled-amount
	//       "field-cash-amount": "0.001530630000000000", // they have fixed it for filled-cash-amount
	//              "field-fees": "0.000003061260000000", // they have fixed it for filled-fees
	//             "finished-at":  1545837948214,
	//                    "source": "spot-api",
	//                     "state": "filled",
	//             "canceled-at":  0                      }
	//
	//     {                  id:  20395337822,
	//                    "symbol": "ethbtc",
	//              "account-id":  5685075,
	//                    "amount": "0.001000000000000000",
	//                     "price": "0.0",
	//              "created-at":  1545831584023,
	//                      "type": "buy-market",
	//            "field-amount": "0.029100000000000000", // they have fixed it for filled-amount
	//       "field-cash-amount": "0.000999788700000000", // they have fixed it for filled-cash-amount
	//              "field-fees": "0.000058200000000000", // they have fixed it for filled-fees
	//             "finished-at":  1545831584181,
	//                    "source": "spot-api",
	//                     "state": "filled",
	//             "canceled-at":  0                      }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(order, "id")
	var side *string = nil
	var typeVar *string = nil
	var status *string = nil
	var orderTypeRaw *string = this.SafeString(order, "type")
	if orderTypeRaw != nil {
		var orderType []string = strings.Split(*orderTypeRaw, "-")
		side = this.SafeString(orderType, 0)
		typeVar = this.SafeString(orderType, 1)
		status = this.ParseOrderStatus(this.SafeString(order, "state"))
	}
	var marketId *string = this.SafeString(order, "symbol")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeInteger(order, "created-at")
	var clientOrderId *string = this.SafeString(order, "client-order-id")
	var amount *string = this.SafeString(order, "amount")
	var filled *string = this.SafeString2(order, "filled-amount", "field-amount") // typo in their API, filled amount
	var price *string = this.SafeString(order, "price")
	var cost *string = this.SafeString2(order, "filled-cash-amount", "field-cash-amount") // same typo
	var feeCost *string = this.SafeString2(order, "filled-fees", "field-fees")            // typo in their API, filled fees
	var fee map[string]any = nil
	if feeCost != nil {
		var feeCurrency any = nil
		if side != nil && *side == "sell" {
			feeCurrency = marketResolved["quote"]
		} else {
			feeCurrency = marketResolved["base"]
		}
		fee = map[string]any{
			"cost":     feeCost,
			"currency": feeCurrency,
		}
	}
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 id,
		"clientOrderId":      clientOrderId,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             marketResolved["symbol"],
		"type":               typeVar,
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"average":            nil,
		"cost":               cost,
		"amount":             amount,
		"filled":             filled,
		"remaining":          nil,
		"status":             status,
		"fee":                fee,
		"trades":             nil,
	}, marketResolved)
}

