func (this *Bittrade) ParseCancelOrders(orders any) []any {
	//
	//    {
	//        "success": [
	//            "5983466"
	//        ],
	//        "failed": [
	//            {
	//                "err-msg": "Incorrect order state",
	//                "order-state": 7,
	//                "order-id": "",
	//                "err-code": "order-orderstate-error",
	//                "client-order-id": "first"
	//            },
	//            ...
	//        ]
	//    }
	//
	//    {
	//        "errors": [
	//            {
	//                "order_id": "769206471845261312",
	//                "err_code": 1061,
	//                "err_msg": "This order doesnt exist."
	//            }
	//        ],
	//        "successes": "1258075374411399168,1258075393254871040"
	//    }
	//
	var successes *string = this.SafeString(orders, "successes")
	var success any = nil
	if successes != nil {
		success = strings.Split(*successes, ",")
	} else {
		success = this.SafeList(orders, "success", []any{})
	}
	var failed []any = SafeList2Typed(orders, "errors", "failed")
	var result []any = []any{}
	for i := 0; i < GetArrayLength(success); i++ {
		var order *string = this.SafeString(success, i)
		result = append(result, OrderToMap(this.SafeOrder(map[string]any{
			"info":   order,
			"id":     order,
			"status": "canceled",
		})))
	}
	for i := 0; i < len(failed); i++ {
		var order any = failed[i]
		result = append(result, OrderToMap(this.SafeOrder(map[string]any{
			"info":          order,
			"id":            this.SafeString2(order, "order-id", "order_id"),
			"status":        "failed",
			"clientOrderId": this.SafeString(order, "client-order-id"),
		})))
	}
	return result
}

