func (this *Bittrade) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	// fetchDeposits
	//
	//     {
	//         "id": 8211029,
	//         "type": "deposit",
	//         "currency": "eth",
	//         "chain": "eth",
	//         'tx-hash': "bd315....",
	//         "amount": 0.81162421,
	//         "address": "4b8b....",
	//         'address-tag": '",
	//         "fee": 0,
	//         "state": "safe",
	//         "created-at": 1542180380965,
	//         "updated-at": 1542180788077
	//     }
	//
	// fetchWithdrawals
	//
	//     {
	//         "id": 6908275,
	//         "type": "withdraw",
	//         "currency": "btc",
	//         "chain": "btc",
	//         'tx-hash': "c1a1a....",
	//         "amount": 0.80257005,
	//         "address": "1QR....",
	//         'address-tag": '",
	//         "fee": 0.0005,
	//         "state": "confirmed",
	//         "created-at": 1552107295685,
	//         "updated-at": 1552108032859
	//     }
	//
	// withdraw
	//
	//     {
	//         "status": "ok",
	//         "data": "99562054"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var timestamp *int64 = this.SafeInteger(transaction, "created-at")
	var code *string = this.SafeCurrencyCode(this.SafeString(transaction, "currency"))
	var typeVar *string = this.SafeString(transaction, "type")
	if typeVar != nil && *typeVar == "withdraw" {
		typeVar = SafeStringPtr("withdrawal")
	}
	var feeCost *string = this.SafeString(transaction, "fee")
	if feeCost != nil {
		feeCost = Precise.StringAbs(feeCost)
	}
	return TransactionFromMap(map[string]any{
		"info":        transaction,
		"id":          this.SafeString2(transaction, "id", "data"),
		"txid":        this.SafeString(transaction, "tx-hash"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     this.NetworkIdToCode(this.SafeStringUpper(transaction, "chain"), code),
		"address":     this.SafeString(transaction, "address"),
		"addressTo":   nil,
		"addressFrom": nil,
		"tag":         this.SafeString(transaction, "address-tag"),
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      this.SafeNumber(transaction, "amount"),
		"currency":    code,
		"status":      this.ParseTransactionStatus(this.SafeString(transaction, "state")),
		"updated":     this.SafeInteger(transaction, "updated-at"),
		"comment":     nil,
		"internal":    nil,
		"fee": map[string]any{
			"currency": code,
			"cost":     this.ParseNumber(feeCost),
			"rate":     nil,
		},
	})
}
func (this *Bittrade) ParseTransactionStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"unknown":         "failed",
		"confirming":      "pending",
		"confirmed":       "ok",
		"safe":            "ok",
		"orphan":          "failed",
		"submitted":       "pending",
		"canceled":        "canceled",
		"reexamine":       "pending",
		"reject":          "failed",
		"pass":            "pending",
		"wallet-reject":   "failed",
		"confirm-error":   "failed",
		"repealed":        "failed",
		"wallet-transfer": "pending",
		"pre-transfer":    "pending",
	}
	return this.SafeString(statuses, status, status)
}

/**
 * @method
 * @name bittrade#withdraw
 * @description make a withdrawal
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.tag] memo / destination tag, required for currencies in options['withdrawTagRequiredCurrencies']
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Bittrade) WithdrawAsync(code string, amount any, address any, optionalArgs ...any) <-chan AsyncResult[Transaction] {
	ch := make(chan AsyncResult[Transaction], 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Bittrade) withdrawBody(ch chan AsyncResult[Transaction], code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var tagWithdrawTag *string = nil
	tagWithdrawTag, paramsWithdrawTag := this.HandleParamString(params, "tag")
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	this.CheckAddress(address, code, tagWithdrawTag)
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"address":  address,
		"amount":   amount,
		"currency": this.SafeStringLower(currency, "id"),
	}
	if tagWithdrawTag != nil {
		request["addr-tag"] = *tagWithdrawTag // only for XRP?
	}
	var network *string = this.SafeStringUpper(paramsWithdrawTag, "network")
	if network != nil {
		network = this.SafeString(this.NetworkAliases, network, network) // accepts aliases like ETH for ERC20
	}
	network = this.SafeStringLower(this.Options["networks"], network, network) // handle ETH>ERC20 alias
	if network != nil {
		// possible chains - usdterc20, trc20usdt, hrc20usdt, usdt, algousdt
		if network != nil && *network == "erc20" {
			request["chain"] = currency["id"].(string) + *network
		} else {
			request["chain"] = *network + currency["id"].(string)
		}
	}
	var paramsNetwork map[string]any = func() map[string]any {
		if network != nil {
			return this.OmitDict(paramsWithdrawTag, "network")
		}
		return paramsWithdrawTag
	}()

	r1 := <-this.PrivatePostDwWithdrawApiCreate(this.Extend(request, paramsNetwork))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	//     {
	//         "status": "ok",
	//         "data": "99562054"
	//     }
	//
	ch <- AsyncResult[Transaction]{Value: this.ParseTransaction(response, currency)}
	return nil
}
func (this *Bittrade) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var apiName string = api[0]
	var requestHeaders any = nil
	var requestBody *string = nil
	var url string = "/"
	if apiName == "market" {
		url += "market"
	} else if (apiName == "public") || (apiName == "private") {
		url += this.Version
	} else if (apiName == "v2Public") || (apiName == "v2Private") {
		url += "v2"
	}
	url += "/" + this.ImplodeParams(path, params)
	var query any = this.Omit(params, this.ExtractParams(path))
	if (apiName == "private") || (apiName == "v2Private") {
		this.CheckRequiredCredentials()
		var timestamp string = this.Ymdhms(this.Milliseconds(), "T")
		var request map[string]any = map[string]any{
			"SignatureMethod":  "HmacSHA256",
			"SignatureVersion": "2",
			"AccessKeyId":      this.ApiKey,
			"Timestamp":        timestamp,
		}
		if method != "POST" {
			request = this.Extend(request, query)
		}
		var requestSorted map[string]any = this.Keysort(request)
		var auth string = this.Urlencode(requestSorted)
		// unfortunately, PHP demands double quotes for the escaped newline symbol
		// eslint-disable-next-line quotes
		var payload string = method + "\n" + this.Hostname + "\n" + url + "\n" + auth
		var signature string = this.Hmac(this.Encode(payload), this.Encode(this.Secret), sha256, "base64")
		auth += "&" + this.Urlencode(map[string]any{
			"Signature": signature,
		})
		url += "?" + auth
		if method == "POST" {
			jsonText := this.Json(query)
			requestBody = &jsonText
			requestHeaders = map[string]any{
				"Content-Type": "application/json",
			}
		} else {
			requestHeaders = map[string]any{
				"Content-Type": "application/x-www-form-urlencoded",
			}
		}
	} else {
		if paramsMap, _ := params.(map[string]any); len(paramsMap) > 0 {
			url += "?" + this.Urlencode(params)
		}
	}
	var baseApiUrl *string = this.SafeString(this.Urls["api"], apiName)
	if baseApiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	url = this.ImplodeParams(baseApiUrl, map[string]any{
		"hostname": this.Hostname,
	}) + url
	var headersResult any = requestHeaders
	var bodyResult *string = requestBody
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    bodyResult,
		"headers": headersResult,
	}
}
func (this *Bittrade) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil // fallback to default error handler
	}
	if this.SafeString(response, "status") != nil {
		//
		//     {"status":"error","err-code":"order-limitorder-amount-min-error","err-msg":"limit order amount error, min: `0.001`","data":null}
		//
		var status *string = this.SafeString(response, "status")
		if status != nil && *status == "error" {
			var codeError *string = this.SafeString(response, "err-code")
			var feedback string = this.Id + " " + body
			this.ThrowBroadlyMatchedException(this.Exceptions["broad"], body, feedback)
			this.ThrowExactlyMatchedException(this.Exceptions["exact"], codeError, feedback)
			var message *string = this.SafeString(response, "err-msg")
			this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, feedback)
			panic(ExchangeError(feedback))
		}
	}
	return nil
}

func NewBittrade(userConfig map[string]any) *Bittrade {
	p := newBittrade()
	p.Init(userConfig)
	return p
}

func (this *Bittrade) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

